SELECT a.bucket_date, a.tier_key, a.player_count, a.sort_order FROM public.rta_agg_tier_daily a WHERE a.season_code = #{seasonCode}
AND a.bucket_date >= (#{seasonStart})::date AND a.bucket_date < (#{seasonEnd})::date
ORDER BY a.bucket_date, a.sort_order
